// Generated by reading the Rust backend (src/models.rs, src/web/*.rs, src/analysis/*.rs).
// Pure type declarations — no runtime code.
//
// Conventions used throughout:
//
// * `DateTime<Utc>` (chrono + serde) serializes as an RFC 3339 / ISO 8601 string in UTC,
//   e.g. "2024-01-15T17:30:00.123456789Z". Typed here as `IsoDateTime`.
// * `NaiveDate` serializes as "YYYY-MM-DD". Typed here as `IsoDate`.
// * Rust `Option<T>` becomes `T | null` — the key is ALWAYS present in the JSON.
//   No struct in this backend uses `skip_serializing_if`, so there are no optional keys
//   in any response. Request bodies are typed the same way, but mind the asymmetry:
//   serde's derive DESERIALIZES a missing `Option<T>` as `None` with no attribute needed.
//   Omitting a nullable key from a PUT body therefore CLEARS it server-side rather than
//   leaving it untouched — always send the field explicitly. (This is what silently wiped
//   `receiptNumber` on every transaction edit; see the FIXME in containers/TransactionDialog.)
// * Money on `Transaction` (`amount`, `fees`) is an integer number of CENTS (Rust i64).
//   Everything computed in src/analysis/* is a plain f64 in currency units (euros), not cents.
// * Almost every struct carries `#[serde(rename_all = "camelCase")]`. The exceptions are
//   noted inline — `Portfolio`, `Position`, `PortfolioSnapshot`, `DataSource`,
//   `PortfolioPlot`, `PortfolioPlotDataPoint` and `StockPlot` have NO rename attribute,
//   so `Position.data_source` really is snake_case on the wire.

// ---------------------------------------------------------------------------
// Scalar aliases
// ---------------------------------------------------------------------------

// chrono NaiveDate — "YYYY-MM-DD" (e.g. "2024-01-15")
export type IsoDate = string;

// chrono DateTime<Utc> — RFC 3339 in UTC (e.g. "2024-01-15T17:30:00.123456789Z")
export type IsoDateTime = string;

// ---------------------------------------------------------------------------
// Core DB models (src/models.rs)
// ---------------------------------------------------------------------------

// Rust: models::Account
// Routes: GET /api/accounts, GET /api/accounts/<id>, POST /api/accounts (response),
//         PUT /api/accounts/<id> (request body)
export interface Account {
  id: number;
  userId: number;
  name: string;
  iban: string | null;
}

// Rust: models::NewAccount
// Route: POST /api/accounts (request body). `userId` is overwritten server-side
// with the authenticated user's id, but the field must still be present.
export interface NewAccount {
  userId: number;
  name: string;
  iban: string | null;
}

// Rust: models::Transaction
// Routes: GET /api/transactions, GET /api/transactions/<id>, POST /api/transactions (response),
//         PUT /api/transactions/<id> (request body), POST /api/receipts (response),
//         and embedded in Position / PositionPerformance.
export interface Transaction {
  id: number;
  accountId: number;
  isin: string;
  date: IsoDateTime;
  units: number;
  // -units*price in CENTS (or the plain amount for dividends); excludes fees.
  // Negative sign means money was given away.
  amount: number;
  // In CENTS; sign should be negative.
  fees: number;
  onvistaExchangeId: number | null;
  comments: string;
  exchange: string | null;
  receiptNumber: number | null;
}

// Rust: models::NewTransaction
// Route: POST /api/transactions (request body)
export interface NewTransaction {
  accountId: number;
  isin: string;
  date: IsoDateTime;
  units: number;
  // CENTS, see Transaction.amount
  amount: number;
  // CENTS, see Transaction.fees
  fees: number;
  onvistaExchangeId: number | null;
  comments: string;
  exchange: string | null;
  receiptNumber: number | null;
}

// Rust: models::StockExchange
// Routes: embedded in PortfolioPlot.exchanges, StockPlot.exchanges and DataSource.exchange
export interface StockExchange {
  isin: string;
  name: string;
  code: string;
  quality: string | null;
  // ID specific to exchange+stock
  onvistaRecordId: number;
  // ID specific to exchange only
  onvistaExchangeId: number | null;
}

// Rust: models::HistoricalPrice
// Routes: GET /api/stocks/prices/historical/<record>,
//         embedded in Portfolio<HistoricalPrice> and in EitherPrice variants
export interface HistoricalPrice {
  date: IsoDate;
  opening: number;
  closing: number;
  high: number;
  low: number;
  volume: number;
  onvistaRecordId: number;
}

// Rust: models::RealtimePrice
// Routes: embedded in Portfolio<RealtimePrice> and in the EitherPrice "RealtimePrice" variant
export interface RealtimePrice {
  date: IsoDateTime;
  price: number;
  onvistaRecordId: number;
}

// Rust: models::User — never serialized by the HTTP API (contains the password hash).
// Listed only for completeness of src/models.rs; the API exposes UserInfo instead.
export interface User {
  id: number;
  name: string;
  fullName: string;
  hash: string;
}

// Rust: models::StockInfo — the raw DB row. Not returned directly by any route;
// GET /api/stocks{,/<isin>} return the derived `Stock` type below, which drops
// `benchmarkIndex` / `instrumentId` and adds `exchanges` / `index`.
export interface StockInfo {
  isin: string;
  wkn: string;
  title: string;
  kind: string;
  company: string;
  fondsType: string | null;
  focus: string | null;
  persistent: boolean;
  onvistaUrl: string;
  lastHistoricalUpdate: IsoDateTime | null;
  lastRealtimeUpdate: IsoDateTime | null;
  industryBreakdown: string | null;
  instrumentBreakdown: string | null;
  countryBreakdown: string | null;
  currencyBreakdown: string | null;
  holdings: string | null;
  launchDate: IsoDateTime | null;
  currency: string | null;
  managementType: string | null;
  payoutType: string | null;
  ter: number | null;
  description: string | null;
  benchmarkIndex: string | null;
  instrumentId: string | null;
}

// ---------------------------------------------------------------------------
// Stocks (src/web/stocks.rs)
// ---------------------------------------------------------------------------

// Rust: web::stocks::Price (private struct, no rename_all — both fields are single words)
// Route: embedded in Exchange.currentPrice
export interface StockExchangeCurrentPrice {
  date: IsoDateTime;
  price: number;
}

// Rust: web::stocks::Exchange
// Route: embedded in Stock.exchanges (GET /api/stocks, GET /api/stocks/<isin>)
export interface Exchange {
  isin: string;
  name: string;
  code: string;
  quality: string | null;
  // ID specific to exchange+stock
  onvistaRecordId: number;
  // ID specific to exchange only
  onvistaExchangeId: number | null;
  currentPrice: StockExchangeCurrentPrice | null;
}

// Rust: web::stocks::Stock
// Routes: GET /api/stocks, GET /api/stocks/<isin>
export interface Stock {
  isin: string;
  wkn: string;
  title: string;
  kind: string;
  company: string;
  fondsType: string | null;
  focus: string | null;
  persistent: boolean;
  onvistaUrl: string;
  lastHistoricalUpdate: IsoDateTime | null;
  lastRealtimeUpdate: IsoDateTime | null;
  // JSON string; parse with JSON.parse() to get a StockBreakdownEntry[]
  industryBreakdown: string | null;
  // JSON string; parse with JSON.parse() to get a StockBreakdownEntry[]
  instrumentBreakdown: string | null;
  // JSON string; parse with JSON.parse() to get a StockBreakdownEntry[]
  countryBreakdown: string | null;
  // JSON string; parse with JSON.parse() to get a StockBreakdownEntry[]
  currencyBreakdown: string | null;
  // JSON string; parse with JSON.parse() to get a StockHolding[]
  holdings: string | null;
  launchDate: IsoDateTime | null;
  currency: string | null;
  managementType: string | null;
  payoutType: string | null;
  ter: number | null;
  description: string | null;
  exchanges: Exchange[];
  // Derived server-side from `description` via a regex over index names
  // (MSCI / iSTOXX / STOXX / S&P / Dow Jones).
  index: string | null;
}

// Shape of one entry inside the JSON *strings* Stock.industryBreakdown /
// instrumentBreakdown / countryBreakdown / currencyBreakdown. The backend stores
// onvista's JSON verbatim (src/onvista/etf.rs), so this is not validated by Rust.
// Fields below are the ones the frontend actually reads
// (web/src/components/portfolioAnalysis/Breakdowns.jsx).
// TODO: verify — onvista may include further keys; only these two are consumed today.
export interface StockBreakdownEntry {
  nameBreakdown: string;
  investmentPct: number;
}

// Shape of one entry inside the JSON *string* Stock.holdings. Stored verbatim from
// onvista (`fundsHoldingList.list`), so likewise not validated by Rust.
// TODO: verify — onvista may include further keys; only these are consumed today.
export interface StockHolding {
  instrument: {
    name: string;
  };
  investmentPct: number;
}

// ---------------------------------------------------------------------------
// User / auth (src/web/user.rs)
// ---------------------------------------------------------------------------

// Rust: web::user::UserInfo
// Routes: GET /api/user (200 when logged in; 401 with an all-null body carrying only
//         `redirect` when not), POST /api/user/login (200 on success)
export interface UserInfo {
  id: number | null;
  name: string | null;
  fullName: string | null;
  // Only ever non-null on the 401 response of GET /api/user, when the server is
  // configured with an external authentication redirect.
  redirect: string | null;
}

// Rust: web::user::LoginData
// Route: POST /api/user/login (request body)
export interface LoginData {
  userName: string;
  password: string;
}

// ---------------------------------------------------------------------------
// Receipts (src/web/receipts.rs)
// ---------------------------------------------------------------------------

// Rust: web::receipts::FileContents (no rename_all)
// Route: POST /api/receipts (request body is FileContents[])
export interface FileContents {
  name: string;
  // base64 encoded file contents (standard alphabet, padded)
  bytes: string;
}

// Rust: web::receipts::ErrString (no rename_all)
// Route: POST /api/receipts (error response body)
export interface ErrString {
  error: string;
}

// ---------------------------------------------------------------------------
// Prices used by the analysis endpoints (src/analysis/price.rs)
// ---------------------------------------------------------------------------

// Rust: analysis::price::EitherPrice — an internally tagged enum, `#[serde(tag = "type")]`.
// The wrapped struct's own (camelCase) fields are inlined next to the discriminator.
// Note that the "HistoricalPrice" and "HistoricalPriceOpening" variants carry the exact
// same payload; they differ only in which field is treated as the price
// (closing vs. opening) by the backend.
// Routes: embedded in PositionSnapshot.dataSource (GET /api/analysis/performance)
export type EitherPrice =
  | ({ type: 'RealtimePrice' } & RealtimePrice)
  | ({ type: 'HistoricalPrice' } & HistoricalPrice)
  | ({ type: 'HistoricalPriceOpening' } & HistoricalPrice);

// Rust: analysis::price::DataSource<T> (no rename_all — both fields are single words)
// Routes: Position.data_source (GET /api/analysis/portfolio),
//         PositionSnapshot.dataSource (GET /api/analysis/performance)
export interface DataSource<T> {
  price: T;
  exchange: StockExchange;
}

// ---------------------------------------------------------------------------
// Portfolio (src/analysis/portfolio.rs)
// ---------------------------------------------------------------------------

// Rust: analysis::portfolio::Position<T> — NO rename_all, so `data_source` is snake_case.
// Route: embedded in Portfolio.stocks
export interface Position<T> {
  isin: string;
  units: number;
  // Sum of (amount + fees) / 100 over all transactions, i.e. in currency units.
  // Negative when money was spent.
  invested: number;
  value: number | null;
  // Internal rate of return, annualized (365d basis). null when no price is available.
  irr: number | null;
  // snake_case on the wire — the Rust struct has no rename_all attribute.
  data_source: DataSource<T> | null;
  transactions: Transaction[];
}

// Rust: analysis::portfolio::Portfolio<T> — NO rename_all.
// Routes: GET /api/analysis/portfolio (T = RealtimePrice),
//         GET /api/analysis/portfolio?date=YYYY-MM-DD (T = HistoricalPrice)
export interface Portfolio<T> {
  invested: number;
  value: number | null;
  // Annualized internal rate of return (365d basis)
  irr: number | null;
  stocks: Position<T>[];
}

// Convenience aliases for the two concrete instantiations the API returns.
export type RealtimePortfolio = Portfolio<RealtimePrice>;
export type HistoricalPortfolio = Portfolio<HistoricalPrice>;

// ---------------------------------------------------------------------------
// Performance (src/analysis/performance.rs)
// ---------------------------------------------------------------------------

// Rust: analysis::performance::PerformanceKind — a plain unit-variant enum, so it
// serializes as one of these string literals (no rename_all applies).
export type PerformanceKind =
  | 'Total'
  | 'Today'
  | 'YearToDate'
  | 'MonthToDate'
  | 'WeekToDate'
  | 'YearToYear'
  | 'MonthToMonth';

// Rust: analysis::performance::PortfolioSnapshot — NO rename_all (all fields single words).
// Route: embedded in PortfolioPerformance.start / .end
export interface PortfolioSnapshot {
  date: IsoDate;
  invested: number;
  // Already included in `invested`
  fees: number;
  value: number | null;
}

// Rust: analysis::performance::PositionSnapshot
// Route: embedded in PositionPerformance.start / .end
export interface PositionSnapshot {
  date: IsoDate;
  units: number;
  invested: number;
  // Already included in `invested`
  fees: number;
  value: number | null;
  dataSource: DataSource<EitherPrice> | null;
}

// Rust: analysis::performance::PositionPerformance
// Route: values of PortfolioPerformance.positions
export interface PositionPerformance {
  start: PositionSnapshot;
  end: PositionSnapshot;
  // Internal rate of return, annualized to a 365 day basis
  irrAnnual: number | null;
  // Internal rate of return over the period between `start.date` and `end.date`
  irrPeriod: number | null;
  transactions: Transaction[];
}

// Rust: analysis::performance::PortfolioPerformance
// Route: GET /api/analysis/performance (returns PortfolioPerformance[])
export interface PortfolioPerformance {
  kind: PerformanceKind;
  start: PortfolioSnapshot;
  end: PortfolioSnapshot;
  irrAnnual: number | null;
  irrPeriod: number | null;
  // Rust HashMap<String, PositionPerformance>, keyed by ISIN
  positions: Record<string, PositionPerformance>;
}

// ---------------------------------------------------------------------------
// Plots (src/analysis/plots.rs)
// ---------------------------------------------------------------------------

// Rust: analysis::plots::PortfolioPlotDataPoint — NO rename_all (all fields single words).
// Route: embedded in PortfolioPlot.points
export interface PortfolioPlotDataPoint {
  date: IsoDateTime;
  // Note: sign is flipped relative to Portfolio.invested — the plot accumulates
  // -(amount + fees) / 100, so a purchase increases `invested`.
  invested: number;
  value: number | null;
}

// Rust: analysis::plots::PortfolioPlot — NO rename_all.
// Route: GET /api/analysis/plots/portfolio
export interface PortfolioPlot {
  points: PortfolioPlotDataPoint[];
  // One entry per ISIN held, the preferred exchange chosen server-side.
  exchanges: StockExchange[];
}

// Rust: analysis::plots::StockPlotDataPoint
// Route: embedded in StockPlot.points
export interface StockPlotDataPoint {
  date: IsoDateTime;
  units: number;
  // See PortfolioPlotDataPoint.invested for the sign convention.
  invested: number;
  // Timestamp of the price actually used for this point (may lag `date`).
  priceDate: IsoDateTime | null;
  price: number | null;
  value: number | null;
}

// Rust: analysis::plots::StockPlot — NO rename_all.
// Route: GET /api/analysis/plots/<isin>
export interface StockPlot {
  points: StockPlotDataPoint[];
  // All known exchanges for the requested ISIN.
  exchanges: StockExchange[];
}

// Rust: analysis::plots::DataSourceSelection — not a serde type; it is parsed from the
// `source` query parameter (case-insensitive). "auto" and "automatic" are equivalent,
// and omitting the parameter defaults to automatic. An unrecognized value yields a 404.
export type DataSourceSelection =
  'realtime' | 'historical' | 'auto' | 'automatic';

// ---------------------------------------------------------------------------
// Import / export payloads (src/serialization.rs)
// ---------------------------------------------------------------------------
// These are CLI-only file formats (stockdb import/export). No HTTP route serves them;
// they are included because they describe the same models.

// Rust: serialization::NativeFormat (no rename_all)
export interface NativeFormat {
  users: User[];
  accounts: Account[];
  transactions: Transaction[];
}

// Rust: serialization::DataFormat (no rename_all)
export interface DataFormat {
  realtime_prices: RealtimePrice[];
  historical_prices: HistoricalPrice[];
}
